            key={i}
            className="flex items-center gap-4 p-6 bg-white border border-slate-200 rounded-xl hover:border-indigo-400 hover:shadow-md transition-all text-left group"
          >
            <div className="p-3 bg-slate-50 rounded-xl group-hover:bg-indigo-50 transition-colors">
              {section.icon}
            </div>
            <div className="flex-1">
              <h3 className="font-bold text-slate-900 text-sm">{section.title}</h3>
