          <div className="inline-flex p-3 bg-indigo-600 text-white rounded-2xl mb-4 shadow-lg shadow-indigo-200">
            <BookOpen size={32} />
          </div>
          <h1 className="text-2xl font-bold text-slate-900">Escola Bíblica EAD</h1>
          <p className="text-slate-500 text-sm mt-1">Portal Administrativo Integrado</p>
        </div>

        {error && (
          <div className="mb-6 p-3 bg-red-50 border border-red-100 text-red-600 rounded-lg text-xs flex items-center gap-2">
            <AlertCircle size={16} />
            {error}
          </div>
        )}

        <form onSubmit={handleLogin} className="space-y-4">
          <div className="space-y-1.5">
            <label className="text-xs font-bold text-slate-700 uppercase tracking-wider ml-1">E-mail</label>
            <div className="relative">
              <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="exemplo@igreja.com"
                className="w-full pl-10 pr-4 py-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm"
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-xs font-bold text-slate-700 uppercase tracking-wider ml-1">Senha</label>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                className="w-full pl-10 pr-4 py-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm"
              />
            </div>
          </div>

          <button 
            type="submit"
            disabled={loading}
            className={`w-full bg-slate-900 text-white py-3 rounded-xl font-bold text-sm shadow-lg hover:bg-slate-800 transition-all active:scale-[0.98] ${
              loading ? 'opacity-70 cursor-not-allowed' : ''
            }`}
          >
            {loading ? 'Validando...' : 'Entrar no Painel'}
          </button>
        </form>

        <p className="text-center text-[10px] text-slate-400 mt-8 uppercase font-medium tracking-tighter">
          &copy; {new Date().getFullYear()} Escola Bíblica EAD • Projeto Independente
        </p>
      </div>
    </div>
  );
};

export default LoginView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, deleteDoc,
  doc, serverTimestamp, where, getDocs, orderBy, getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, User, Course, ProfessorSubView, Material, Feedback, 
  Module, Lesson, Question, ScheduledClass
} from './types';
import { 
  CheckSquare, Plus, X, Trash2, FileText, Radio, Layers, Star, 
  ExternalLink, Award, Edit3, Eye, Calendar as CalendarIcon, ClipboardList, 
  PlayCircle, TrendingUp, Tv, PenTool, Users, Mic, MicOff, 
  Video, VideoOff, Monitor, PhoneOff, MessageSquare, Sparkles, 
  RefreshCw, Send, Bell, UserX, VolumeX, ShieldCheck, Settings, 
  Presentation, ChevronLeft, ChevronRight, Upload, Play, 
  ShieldAlert, MoreVertical, Sliders, ImageIcon,
  CheckCircle2, AlertTriangle, Info, Clock, Save, ListOrdered, ArrowLeft,
  ChevronLast, Timer, BarChart3, Activity, PowerOff, UserPlus, ShieldX,
  Link as LinkIcon, Database, Paperclip, MonitorOff
} from 'lucide-react';
import SignaturePad from './components/SignaturePad';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [showLobby, setShowLobby] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [devices, setDevices] = useState<{audio: MediaDeviceInfo[], video: MediaDeviceInfo[]}>({audio: [], video: []});
  const [selectedDevices, setSelectedDevices] = useState({audio: '', video: ''});
  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [activeReactions, setActiveReactions] = useState<{id: number, emoji: string, left: number}[]>([]);
  const [selectedFileUrl, setSelectedFileUrl] = useState<string | null>(null);
  const [showPptUpload, setShowPptUpload] = useState(false);

  // Academic States
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [fullScreenMode, setFullScreenMode] = useState<'none' | 'question_editor' | 'course_preview'>('none');

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState({ title: '', courseId: '', moduleId: '', type: 'activity' as 'activity'|'evaluation', passingGrade: 70 });
  const [questionForm, setQuestionForm] = useState({ text: '', options: ['', '', '', ''], correct: 0 });
  const [currentExam, setCurrentExam] = useState<Exam | null>(null);
  const [selectedDateForSchedule, setSelectedDateForSchedule] = useState<string>('');

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    unsubscribes.push(onSnapshot(collection(db, 'exams'), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid)), (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    if (selectedCourseForModules) {
      unsubscribes.push(onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules)), (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    navigator.mediaDevices.enumerateDevices().then(d => {
      setDevices({
        audio: d.filter(i => i.kind === 'audioinput'),
        video: d.filter(i => i.kind === 'videoinput')
      });
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  const startLiveMedia = async (videoId?: string, audioId?: string) => {
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    try {
      const constraints = {
        video: videoId ? { deviceId: { exact: videoId } } : true,
        audio: audioId ? { deviceId: { exact: audioId } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      if (lobbyVideoRef.current) lobbyVideoRef.current.srcObject = stream;
    } catch (err) { console.error("Media Error:", err); }
  };

  const startLobby = async () => {
    setShowLobby(true);
    await startLiveMedia();
  };

  const toggleMic = () => {
    if (streamRef.current) {
      const track = streamRef.current.getAudioTracks()[0];
      if (track) { track.enabled = !track.enabled; setMicActive(track.enabled); }
    }
  };

  const toggleVideo = () => {
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      if (track) { track.enabled = !track.enabled; setVideoActive(track.enabled); }
    }
  };

  const triggerReaction = (emoji: string) => {
    const id = Date.now();
    setActiveReactions(prev => [...prev, { id, emoji, left: Math.random() * 80 + 10 }]);
    setTimeout(() => setActiveReactions(prev => prev.filter(r => r.id !== id)), 2500);
  };

  const handleSaveLesson = async () => {
    if (!currentModuleId || !lessonForm.title) return;
    const modRef = doc(db, 'modulos', currentModuleId);
    const modSnap = await getDoc(modRef);
    if (!modSnap.exists()) return;
    const moduleData = modSnap.data() as Module;
    let lessons = [...(moduleData.lessons || [])];
    if (editingLessonId) {
      lessons = lessons.map(l => l.id === editingLessonId ? { ...l, ...lessonForm } : l);
    } else {
      lessons.push({ id: Math.random().toString(36).substr(2, 9), ...lessonForm, order: lessons.length + 1 });
    }
    await updateDoc(modRef, { lessons });
    setIsLessonModalOpen(false);
  };

  // Calendário Funcional
  const daysInMonth = () => {
    const now = new Date();
    return new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  };

  const renderCalendar = () => {
    const days = [];
    const totalDays = daysInMonth();
    const now = new Date();

    for (let i = 1; i <= totalDays; i++) {
      const dateStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
      const hasClass = scheduledClasses.some(s => s.date.includes(dateStr));

      days.push(
        <button 
          key={i} 
          onClick={() => { setSelectedDateForSchedule(dateStr); setIsScheduleModalOpen(true); }}
          className={`aspect-square rounded-xl flex flex-col items-center justify-center text-[10px] font-bold border transition-all relative
            ${hasClass ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-white border-slate-100 text-slate-400 hover:border-indigo-300'}`}
        >
          {i}
          {hasClass && <div className="absolute bottom-1 w-1 h-1 bg-white rounded-full"></div>}
        </button>
      );
    }
    return days;
  };

  if (loading) return <div className="h-full flex items-center justify-center"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full"></div></div>;

  // VIEW: PREVIEW ALUNO
  if (fullScreenMode === 'course_preview') {
    return (
      <div className="fixed inset-0 z-[1000] bg-white flex flex-col animate-in slide-in-from-right duration-500 overflow-hidden text-slate-900">
        <header className="bg-slate-900 text-white px-8 py-4 flex items-center justify-between shadow-xl">
          <div className="flex items-center gap-4">
            <button onClick={() => setFullScreenMode('none')} className="p-2 hover:bg-white/10 rounded-full"><ArrowLeft size={20}/></button>
            <h2 className="text-base font-black uppercase tracking-tight italic">Ambiente do Aluno (Simulação)</h2>
          </div>
          <button onClick={() => setFullScreenMode('none')} className="px-6 py-2.5 bg-indigo-600 rounded-xl text-[9px] font-black uppercase">Sair</button>
        </header>
        <div className="flex-1 flex overflow-hidden">
          <aside className="w-72 bg-slate-50 border-r border-slate-200 overflow-y-auto p-6">
            <h3 className="text-[9px] font-black uppercase text-slate-400 mb-6 tracking-widest italic">Conteúdo do Curso</h3>
            <div className="space-y-6">
              {modules.map((m, idx) => (
                <div key={m.id} className="space-y-2">
                  <div className="text-[10px] font-black uppercase text-indigo-600 italic">Módulo {idx + 1}: {m.title}</div>
                  <div className="pl-4 space-y-1">
                    {m.lessons.map(l => (
                      <div key={l.id} className="flex items-center gap-2 text-[10px] font-medium text-slate-500 hover:text-indigo-600 cursor-pointer">
                        <PlayCircle size={12}/> {l.title}
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </aside>
          <main className="flex-1 overflow-y-auto p-12 bg-white text-center">
             <div className="max-w-4xl mx-auto aspect-video bg-slate-900 rounded-[2.5rem] flex items-center justify-center text-white/20">
                <Play size={100} />
             </div>
             <h1 className="mt-8 text-3xl font-black uppercase tracking-tighter">Selecione uma aula para começar</h1>
          </main>
        </div>
      </div>
    );
  }

  // SALA DE LIVE ATIVA
  if (isLiveActive) {
    return (
      <div className="fixed inset-0 z-[1200] bg-black flex flex-col text-white overflow-hidden">
        <div className="absolute top-0 left-0 right-0 z-[1300] p-6 flex items-center justify-between pointer-events-none">
           <div className="flex items-center gap-3 pointer-events-auto">
              <div className="bg-rose-600 px-4 py-2 rounded-xl flex items-center gap-2 shadow-2xl border border-rose-500/20"><div className="w-2 h-2 bg-white rounded-full animate-ping"></div><span className="text-[8px] font-black uppercase italic tracking-widest text-white">AO VIVO</span></div>
              <div className="bg-black/60 backdrop-blur-2xl px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3 text-[8px] font-black uppercase tracking-widest"><Users size={14}/> {allStudents.length} ALUNOS</div>
           </div>
           <div className="bg-indigo-600 px-4 py-2 rounded-xl text-[8px] font-black uppercase flex items-center gap-2 shadow-2xl pointer-events-auto text-white"><ShieldCheck size={16}/> {user.displayName}</div>
        </div>

        <div className="flex-1 flex overflow-hidden">
           <div className="flex-1 relative flex items-center justify-center p-10">
              <div className="w-full h-full max-w-[1400px] aspect-video bg-zinc-950 rounded-[2.5rem] overflow-hidden border border-white/5 relative group">
                 {isPresentationMode && selectedFileUrl ? (
                   <iframe src={`https://docs.google.com/viewer?url=${encodeURIComponent(selectedFileUrl)}&embedded=true`} className="w-full h-full border-none bg-white" />
                 ) : (
                   <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover ${videoActive ? 'opacity-100' : 'opacity-0'}`} />
                 )}
                 {!videoActive && !isPresentationMode && <div className="absolute inset-0 bg-zinc-900 flex items-center justify-center text-4xl font-black">{(user.displayName||'U').charAt(0)}</div>}

                 <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-black/80 backdrop-blur-3xl px-8 py-4 rounded-[2.5rem] border border-white/10 shadow-2xl opacity-0 group-hover:opacity-100 transition-all z-[1400]">
                    <button onClick={toggleMic} className={`p-3 rounded-xl ${micActive ? 'bg-white/5' : 'bg-rose-600'}`}>{micActive ? <Mic size={20}/> : <MicOff size={20}/>}</button>
                    <button onClick={toggleVideo} className={`p-3 rounded-xl ${videoActive ? 'bg-white/5' : 'bg-rose-600'}`}>{videoActive ? <Video size={20}/> : <VideoOff size={20}/>}</button>
                    <button onClick={() => setShowPptUpload(true)} className={`p-3 rounded-xl ${isPresentationMode ? 'bg-indigo-600' : 'bg-white/5'}`}><Presentation size={20}/></button>
                    <button onClick={() => setActivePanel(activePanel === 'chat' ? 'none' : 'chat')} className={`p-3 rounded-xl ${activePanel === 'chat' ? 'bg-indigo-600' : 'bg-white/5'}`}><MessageSquare size={20}/></button>
                    <button onClick={() => setIsLiveActive(false)} className="px-6 py-3 bg-rose-600 rounded-xl text-[8px] font-black uppercase flex items-center gap-2"><PhoneOff size={16}/> Encerrar</button>
                 </div>
              </div>
           </div>

           {activePanel === 'chat' && (
             <aside className="w-80 bg-zinc-900 border-l border-white/5 flex flex-col p-6 animate-in slide-in-from-right">
                <div className="flex items-center justify-between mb-6">
                  <h3 className="text-xs font-black uppercase italic tracking-widest">Chat da Aula</h3>
                  <button onClick={() => setActivePanel('none')}><X size={18}/></button>
                </div>
                <div className="flex-1 overflow-y-auto space-y-4 text-[10px]">
                   {chatMessages.map((msg, i) => (
                     <div key={i} className="bg-white/5 p-3 rounded-xl">
                        <p className="font-black text-indigo-400 uppercase mb-1">{msg.user}</p>
                        <p className="text-white/80">{msg.text}</p>
                     </div>
                   ))}
                </div>
                <div className="mt-4 flex gap-2">
                   <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} placeholder="Mensagem..." className="flex-1 bg-white/5 border-none rounded-xl px-4 py-2 text-xs" />
                   <button onClick={() => { if(chatMessage) { setChatMessages([...chatMessages, {user: user.displayName, text: chatMessage, time: 'agora'}]); setChatMessage(''); } }} className="p-2 bg-indigo-600 rounded-xl"><Send size={18}/></button>
                </div>
             </aside>
           )}
        </div>

        {showPptUpload && (
          <div className="fixed inset-0 z-[3000] bg-black/90 backdrop-blur-xl flex items-center justify-center p-8">
            <div className="bg-white w-full max-w-xl rounded-[3rem] p-12 text-slate-900 text-center">
              <h3 className="text-2xl font-black uppercase italic tracking-tighter mb-8">Selecionar Documento</h3>
              <div className="grid grid-cols-1 gap-3 max-h-60 overflow-y-auto pr-2">
                {materials.filter(m => m.type === 'pdf').map(m => (
                  <button key={m.id} onClick={() => { setSelectedFileUrl(m.url); setIsPresentationMode(true); setShowPptUpload(false); }} className="p-4 rounded-xl border-2 border-slate-50 hover:border-indigo-600 text-left flex items-center gap-3">
                    <FileText className="text-indigo-600"/> <span className="font-black text-[10px] uppercase">{m.title}</span>
                  </button>
                ))}
              </div>
              <button onClick={() => setShowPptUpload(false)} className="mt-8 px-8 py-4 bg-slate-100 rounded-xl text-[10px] font-black uppercase italic">Cancelar</button>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20 text-slate-900">
      {/* MATRIZ CURRICULAR */}
      {activeSub === 'modulos' && (
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm flex justify-between items-center">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-xl"><Layers size={22}/></div>
              <h1 className="text-lg font-black uppercase italic tracking-tighter">Matriz Acadêmica</h1>
            </div>
            <div className="flex gap-3">
              <button onClick={() => setFullScreenMode('course_preview')} className="bg-slate-100 text-slate-600 px-5 py-3 rounded-xl text-[8px] font-black uppercase">Preview Aluno</button>
              <button onClick={() => { setModuleTitle(''); setCurrentModuleId(null); setIsModuleModalOpen(true); }} className="bg-indigo-600 text-white px-6 py-3 rounded-xl text-[8px] font-black uppercase italic shadow-lg">Novo Módulo</button>
            </div>
          </div>

          <div className="grid grid-cols-1 gap-6">
            {modules.map(mod => (
              <div key={mod.id} className="bg-white border border-slate-100 rounded-[2rem] overflow-hidden shadow-sm">
                  <div className="bg-slate-50 px-8 py-4 border-b flex justify-between items-center">
                    <h3 className="font-black text-slate-800 text-sm uppercase italic">#{mod.order} - {mod.title}</h3>
                    <div className="flex gap-2">
                      <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(null); setLessonForm({title:'', videoUrl:'', description:'', materialUrl:''}); setIsLessonModalOpen(true); }} className="px-4 py-2 bg-indigo-600 text-white text-[8px] font-black uppercase rounded-lg">Add Aula</button>
                      <button onClick={async () => { if(confirm('Excluir módulo?')) await deleteDoc(doc(db, 'modulos', mod.id)); }} className="p-2 text-rose-600"><Trash2 size={16}/></button>
                    </div>
                  </div>
                  <div className="p-6 space-y-3">
                    {mod.lessons.map((l, i) => (
                      <div key={l.id} className="bg-slate-50 p-4 rounded-xl flex justify-between items-center group">
                        <span className="font-black uppercase italic text-slate-900 text-xs">{i+1}. {l.title}</span>
                        <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-all">
                          <button onClick={() => { setCurrentModuleId(mod.id); setEditingLessonId(l.id); setLessonForm({title:l.title, videoUrl:l.videoUrl, description:l.description||'', materialUrl:l.materialUrl||''}); setIsLessonModalOpen(true); }} className="p-2 text-indigo-600"><Edit3 size={14}/></button>
                          <button onClick={async () => { 
                            if(confirm('Excluir aula?')) {
                              const lessons = mod.lessons.filter(item => item.id !== l.id);
                              await updateDoc(doc(db, 'modulos', mod.id), { lessons });
                            }
                          }} className="p-2 text-rose-600"><Trash2 size={14}/></button>
                        </div>
                      </div>
                    ))}
                    {mod.lessons.length === 0 && <p className="text-center py-4 text-slate-300 text-[10px] font-black uppercase italic">Nenhuma aula neste módulo.</p>}
                  </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* AVALIAÇÕES */}
      {activeSub === 'avaliacao' && (
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm flex justify-between items-center">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-amber-500 text-white rounded-2xl shadow-xl"><Award size={22}/></div>
              <h1 className="text-lg font-black uppercase italic tracking-tighter">Avaliações e Provas</h1>
            </div>
            <button onClick={() => { setExamForm({title:'', courseId: selectedCourseForModules, moduleId: '', type:'activity', passingGrade: 70}); setCurrentExam(null); setIsExamModalOpen(true); }} className="bg-slate-900 text-white px-6 py-3 rounded-xl text-[8px] font-black uppercase italic shadow-lg">Nova Prova</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {exams.filter(e => e.courseId === selectedCourseForModules).map(e => (
              <div key={e.id} className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm relative group hover:border-indigo-400 transition-all">
                <div className="flex justify-between mb-6">
                   <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase ${e.type === 'evaluation' ? 'bg-rose-100 text-rose-600' : 'bg-indigo-100 text-indigo-600'}`}>{e.type}</span>
                   <div className="flex gap-2">
                      <button onClick={() => { setExamForm({title:e.title, courseId:e.courseId, moduleId:e.moduleId, type:e.type, passingGrade:e.passingGrade}); setCurrentExam(e); setIsExamModalOpen(true); }} className="text-slate-400 hover:text-indigo-600"><Edit3 size={16}/></button>
                      <button onClick={async () => { if(confirm('Excluir prova?')) await deleteDoc(doc(db, 'exams', e.id)); }} className="text-slate-400 hover:text-rose-600"><Trash2 size={16}/></button>
                   </div>
                </div>
                <h3 className="text-xl font-black uppercase italic tracking-tighter mb-4">{e.title}</h3>
                <div className="flex justify-between text-[10px] font-black uppercase text-slate-400 mt-auto">
