                <h4 className="text-[10px] font-black uppercase italic line-clamp-1 mb-4">{m.title}</h4>
                <a href={m.url} target="_blank" className="text-[8px] font-black uppercase bg-slate-900 text-white px-4 py-2 rounded-lg block">Abrir</a>
                <button onClick={async () => { if(confirm('Remover?')) await deleteDoc(doc(db, 'materials', m.id)); }} className="absolute top-2 right-2 text-rose-500 opacity-0 group-hover:opacity-100"><Trash2 size={14}/></button>
