             <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-indigo-50 p-6 rounded-2xl text-center">
                   <p className="text-4xl font-black text-indigo-600">{feedbacks.length}</p>
                   <p className="text-[8px] font-black uppercase text-indigo-400 mt-2">Total Recebido</p>
                </div>
                <div className="bg-emerald-50 p-6 rounded-2xl text-center">
                   <p className="text-4xl font-black text-emerald-600">{feedbacks.filter(f => f.type === 'elogio').length}</p>
                   <p className="text-[8px] font-black uppercase text-emerald-400 mt-2">Elogios</p>
