      {/* DIÁRIO / FREQUÊNCIA / RELATÓRIO */}
      {['diario', 'frequencia', 'relatorio'].includes(activeSub) && (
        <div className="bg-white p-8 rounded-[2rem] border border-slate-200">
           <h1 className="text-2xl font-black uppercase italic tracking-tighter mb-8">{activeSub === 'diario' ? 'Diário de Classe' : activeSub === 'frequencia' ? 'Frequência Discente' : 'Relatório Geral'}</h1>
           <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black uppercase text-slate-400">
                 <tr><th className="px-6 py-4">Aluno</th><th className="px-6 py-4">Progresso</th><th className="px-6 py-4">Status</th></tr>
              </thead>
              <tbody>
                 {allStudents.map(s => (
                   <tr key={s.uid} className="border-b border-slate-50">
                      <td className="px-6 py-4 font-black text-xs uppercase italic">{s.displayName}</td>
                      <td className="px-6 py-4"><div className="w-full h-1.5 bg-slate-100 rounded-full"><div className="w-2/3 h-full bg-indigo-600 rounded-full"></div></div></td>
                      <td className="px-6 py-4"><span className="text-[8px] font-black uppercase bg-emerald-100 text-emerald-600 px-3 py-1 rounded-lg">Ativo</span></td>
