              </tbody>
           </table>
        </div>
      )}

      {/* AULA AO VIVO (SETUP & CALENDÁRIO) */}
      {activeSub === 'live' && !isLiveActive && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-full">
           {showLobby ? (
             <div className="fixed inset-0 z-[2000] bg-slate-950/95 flex items-center justify-center p-6">
                <div className="bg-white w-full max-w-4xl rounded-[3rem] overflow-hidden flex flex-col md:flex-row shadow-2xl">
                   <div className="flex-1 bg-black relative flex items-center justify-center">
                      <video ref={lobbyVideoRef} autoPlay playsInline muted className={`w-full h-full object-cover ${videoActive ? 'opacity-100' : 'opacity-0'}`} />
                      <div className="absolute bottom-6 flex gap-3">
                         <button onClick={toggleMic} className={`p-3 rounded-xl ${micActive ? 'bg-white/10 text-white' : 'bg-rose-600 text-white'}`}><Mic size={20}/></button>
                         <button onClick={toggleVideo} className={`p-3 rounded-xl ${videoActive ? 'bg-white/10 text-white' : 'bg-rose-600 text-white'}`}><Video size={20}/></button>
                      </div>
                   </div>
                   <div className="w-full md:w-96 p-12 space-y-8 flex flex-col justify-center text-center">
                      <h3 className="text-3xl font-black uppercase italic tracking-tighter">Setup da Aula</h3>
                      <button onClick={() => setIsLiveActive(true)} className="w-full py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-2xl italic tracking-[0.2em]">Iniciar a Aula</button>
                      <button onClick={() => setShowLobby(false)} className="text-[10px] font-black uppercase text-slate-400">Voltar</button>
                   </div>
                </div>
