           ) : (
             <>
               <div className="bg-white p-12 rounded-[3.5rem] border border-slate-200 shadow-sm text-center flex flex-col items-center justify-center">
                 <div className="w-20 h-20 bg-rose-50 rounded-[2rem] flex items-center justify-center mb-8"><Radio size={40} className="text-rose-600" /></div>
                 <h2 className="text-3xl font-black uppercase tracking-tighter mb-4 italic">Sala Virtual Master</h2>
                 <p className="text-slate-400 text-[10px] font-medium uppercase tracking-widest italic mb-10 max-w-xs">Inicie sua transmissão ao vivo agora para todos os alunos matriculados.</p>
                 <button onClick={startLobby} className="bg-slate-900 text-white px-12 py-5 rounded-2xl text-[10px] font-black uppercase italic shadow-2xl tracking-[0.2em]">Iniciar a Aula</button>
               </div>

               <div className="bg-white p-8 rounded-[3.5rem] border border-slate-200 shadow-sm flex flex-col">
                 <h3 className="font-black uppercase text-xs italic tracking-widest mb-8">Calendário Acadêmico (Clique no Dia)</h3>
                 <div className="grid grid-cols-7 gap-2 mb-4 text-center">
                   {['D', 'S', 'T', 'Q', 'Q', 'S', 'S'].map(d => <span key={d} className="text-[10px] font-black text-slate-300">{d}</span>)}
                 </div>
                 <div className="grid grid-cols-7 gap-2">
                   {renderCalendar()}
                 </div>
                 <div className="mt-8 space-y-3">
                   {scheduledClasses.slice(0, 3).map(s => (
                     <div key={s.id} className="p-4 bg-slate-50 rounded-2xl flex justify-between items-center text-[10px] font-black uppercase italic">
                        <span>{s.title}</span>
                        <span className="text-indigo-600">{s.date}</span>
                     </div>
                   ))}
                 </div>
               </div>
             </>
           )}
