      )}

      {/* MODAL: NOVA AULA Master */}
      {isLessonModalOpen && (
        <div className="fixed inset-0 z-[2000] bg-slate-950/80 backdrop-blur-2xl flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-lg rounded-[3rem] p-12 space-y-6 text-slate-900">
            <h3 className="text-2xl font-black uppercase italic tracking-tighter">{editingLessonId ? 'Editar Aula' : 'Nova Aula Master'}</h3>
            <div className="space-y-4">
              <input value={lessonForm.title} onChange={e => setLessonForm({...lessonForm, title: e.target.value})} placeholder="Título da Aula" className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" />
              <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="Link do Vídeo" className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" />

              <div className="space-y-2">
                <label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Material de Apoio (Link ou Biblioteca)</label>
                <div className="flex gap-2">
                  <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="Link do Material..." className="flex-1 px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" />
                  <select onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} className="px-6 py-4 bg-indigo-50 border-none rounded-2xl font-black text-[10px] uppercase text-indigo-600">
                    <option value="">Da Biblioteca...</option>
                    {materials.map(m => <option key={m.id} value={m.url}>{m.title}</option>)}
                  </select>
                </div>
              </div>

              <textarea value={lessonForm.description} onChange={e => setLessonForm({...lessonForm, description: e.target.value})} placeholder="Resumo Pedagógico" className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl h-24 font-medium text-xs resize-none" />
            </div>
            <div className="flex gap-3">
              <button onClick={() => setIsLessonModalOpen(false)} className="flex-1 py-5 bg-slate-100 rounded-2xl text-[9px] font-black uppercase italic">Cancelar</button>
              <button onClick={handleSaveLesson} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase shadow-2xl">Gravar Aula</button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL: EXAME */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[2000] bg-slate-950/80 backdrop-blur-2xl flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 space-y-6 text-slate-900">
            <h3 className="text-2xl font-black uppercase italic tracking-tighter">Configuração de Prova</h3>
            <div className="space-y-4">
              <input value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Título da Avaliação" className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" />
              <div className="grid grid-cols-2 gap-4">
                <input type="number" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: Number(e.target.value)})} placeholder="Média %" className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" />
                <select value={examForm.type} onChange={e => setExamForm({...examForm, type: e.target.value as any})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase">
                  <option value="activity">Atividade</option>
                  <option value="evaluation">Prova Final</option>
                </select>
              </div>
            </div>
            <div className="flex gap-3">
              <button onClick={() => setIsExamModalOpen(false)} className="flex-1 py-5 bg-slate-100 rounded-2xl text-[9px] font-black uppercase italic">Sair</button>
              <button onClick={async () => {
                const payload = { ...examForm, authorId: user.uid, questions: currentExam?.questions || [], createdAt: serverTimestamp() };
                if(currentExam) await updateDoc(doc(db, 'exams', currentExam.id), payload);
                else await addDoc(collection(db, 'exams'), payload);
                setIsExamModalOpen(false);
              }} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase italic">Gravar</button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL: MÓDULO Master */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 text-center text-slate-900">
            <h3 className="text-2xl font-black uppercase italic tracking-tighter mb-8">{currentModuleId ? 'Editar Módulo' : 'Novo Módulo Master'}</h3>
            <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título do Módulo..." className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs mb-8" />
            <div className="flex gap-3">
              <button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-5 bg-slate-100 rounded-2xl text-[9px] font-black uppercase italic">Cancelar</button>
              <button onClick={async () => {
                if(!moduleTitle) return;
                if(currentModuleId) await updateDoc(doc(db, 'modulos', currentModuleId), { title: moduleTitle });
                else await addDoc(collection(db, 'modulos'), { courseId: selectedCourseForModules, title: moduleTitle, order: modules.length+1, lessons: [], createdAt: serverTimestamp() });
                setIsModuleModalOpen(false);
              }} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase italic">Gravar Módulo</button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL: AGENDAMENTO CALENDÁRIO */}
      {isScheduleModalOpen && (
        <div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 text-slate-900">
            <h3 className="text-2xl font-black uppercase italic tracking-tighter text-center mb-8">Agendar para {selectedDateForSchedule}</h3>
            <input id="sched-title-final" placeholder="Tema do Encontro..." className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs mb-8" />
            <div className="flex gap-3">
              <button onClick={() => setIsScheduleModalOpen(false)} className="flex-1 py-5 bg-slate-100 rounded-2xl text-[9px] font-black uppercase italic">Sair</button>
              <button onClick={async () => {
                const title = (document.getElementById('sched-title-final') as HTMLInputElement).value;
                if (title) {
                  await addDoc(collection(db, 'scheduledClasses'), { professorId: user.uid, courseId: selectedCourseForModules, title, date: selectedDateForSchedule, status: 'scheduled', createdAt: serverTimestamp() });
                  setIsScheduleModalOpen(false);
                }
              }} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase italic">Confirmar</button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL: MATERIAL */}
      {isMaterialModalOpen && (
        <div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-2xl">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 text-center text-slate-900">
            <h3 className="text-2xl font-black uppercase italic tracking-tighter mb-8">Novo Material Master</h3>
            <div className="space-y-4 mb-8 text-left">
              <input value={materialTitle} onChange={e => setMaterialTitle(e.target.value)} placeholder="Título do Material" className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" />
              <input value={materialUrl} onChange={e => setMaterialUrl(e.target.value)} placeholder="Link do Arquivo (PDF)" className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" />
            </div>
            <div className="flex gap-3">
              <button onClick={() => setIsMaterialModalOpen(false)} className="flex-1 py-5 bg-slate-100 rounded-2xl text-[9px] font-black uppercase italic">Cancelar</button>
              <button onClick={async () => {
                if(materialTitle && materialUrl) {
                  await addDoc(collection(db, 'materials'), { courseId: selectedCourseForModules, title: materialTitle, url: materialUrl, type: 'pdf', createdAt: serverTimestamp() });
                  setIsMaterialModalOpen(false);
                }
              }} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase italic">Publicar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SchoolManagement;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, deleteDoc,
  doc, serverTimestamp, where, getDocs, orderBy, getDoc
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { 
  Exam, User, Course, ProfessorSubView, Material, Feedback, 
  Module, Lesson, Question, ScheduledClass
} from './types';
import { 
  CheckSquare, Plus, X, Trash2, FileText, Radio, Layers, Star, 
  ExternalLink, Award, Edit3, Eye, Calendar as CalendarIcon, ClipboardList, 
  PlayCircle, TrendingUp, Tv, PenTool, Users, Mic, MicOff, 
  Video, VideoOff, Monitor, PhoneOff, MessageSquare, Sparkles, 
  Send, Bell, ShieldCheck, Settings, 
  Presentation, ChevronLeft, ChevronRight, Play, 
  ShieldAlert, MoreVertical, Sliders, ImageIcon,
  CheckCircle2, AlertTriangle, Info, Clock, Save, ListOrdered, ArrowLeft,
  Timer, BarChart3, Activity, UserPlus, ShieldX,
  Link as LinkIcon, Database, Paperclip, MonitorOff, Volume2, VolumeX, Camera, Slash
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [showLobby, setShowLobby] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [devices, setDevices] = useState<{audio: MediaDeviceInfo[], video: MediaDeviceInfo[]}>({audio: [], video: []});
  const [selectedDevices, setSelectedDevices] = useState({audio: '', video: ''});
  const [bgEffect, setBgEffect] = useState<'none' | 'blur' | 'office' | 'custom'>('none');
  const [globalMute, setGlobalMute] = useState(false);
  const [blockCameras, setBlockCameras] = useState(false);
  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [selectedFileUrl, setSelectedFileUrl] = useState<string | null>(null);
  const [showPptUpload, setShowPptUpload] = useState(false);

  // Academic States
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [fullScreenMode, setFullScreenMode] = useState<'none' | 'exam_editor' | 'course_preview'>('none');

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState<Partial<Exam>>({ title: '', courseId: '', moduleId: '', type: 'activity', passingGrade: 70, questions: [] });
  const [questionForm, setQuestionForm] = useState<Question>({ id: '', text: '', options: ['', '', '', ''], correctOption: 0 });
  const [selectedDateForSchedule, setSelectedDateForSchedule] = useState<string>('');

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    unsubscribes.push(onSnapshot(collection(db, 'exams'), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid)), (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    if (selectedCourseForModules) {
      unsubscribes.push(onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules)), (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    navigator.mediaDevices.enumerateDevices().then(d => {
      const v = d.filter(i => i.kind === 'videoinput');
      const a = d.filter(i => i.kind === 'audioinput');
      setDevices({ audio: a, video: v });
      if (v.length > 0) setSelectedDevices(prev => ({ ...prev, video: v[0].deviceId }));
      if (a.length > 0) setSelectedDevices(prev => ({ ...prev, audio: a[0].deviceId }));
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  const startLiveMedia = async () => {
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    try {
      const constraints = {
        video: selectedDevices.video ? { deviceId: { exact: selectedDevices.video } } : true,
        audio: selectedDevices.audio ? { deviceId: { exact: selectedDevices.audio } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      if (lobbyVideoRef.current) lobbyVideoRef.current.srcObject = stream;
    } catch (err) { console.error("Media Error:", err); }
  };

  const handleSaveLesson = async () => {
    if (!currentModuleId || !lessonForm.title) return;
    const modRef = doc(db, 'modulos', currentModuleId);
    const modSnap = await getDoc(modRef);
    if (!modSnap.exists()) return;
    const moduleData = modSnap.data() as Module;
    let lessons = [...(moduleData.lessons || [])];
    if (editingLessonId) {
      lessons = lessons.map(l => l.id === editingLessonId ? { ...l, ...lessonForm } : l);
    } else {
      lessons.push({ id: Math.random().toString(36).substr(2, 9), ...lessonForm, order: lessons.length + 1 });
    }
    await updateDoc(modRef, { lessons });
    setIsLessonModalOpen(false);
  };

  const addQuestionToExam = () => {
    if (!questionForm.text) return;
    const newQ = { ...questionForm, id: Math.random().toString(36).substr(2, 9) };
    setExamForm(prev => ({ ...prev, questions: [...(prev.questions || []), newQ] }));
    setQuestionForm({ id: '', text: '', options: ['', '', '', ''], correctOption: 0 });
  };

  const removeQuestion = (id: string) => {
    setExamForm(prev => ({ ...prev, questions: prev.questions?.filter(q => q.id !== id) }));
  };

  const saveExam = async () => {
    if (!examForm.title) return;
    const payload = { ...examForm, authorId: user.uid, createdAt: serverTimestamp() };
    if (examForm.id) {
      await updateDoc(doc(db, 'exams', examForm.id), payload);
    } else {
      await addDoc(collection(db, 'exams'), payload);
    }
    setFullScreenMode('none');
