  Video, VideoOff, Monitor, PhoneOff, MessageSquare, Sparkles, 
  Send, Bell, ShieldCheck, Settings, 
  Presentation, ChevronLeft, ChevronRight, Play, 
  ShieldAlert, MoreVertical, Sliders, ImageIcon,
  CheckCircle2, AlertTriangle, Info, Clock, Save, ListOrdered, ArrowLeft,
  Timer, BarChart3, Activity, UserPlus, ShieldX,
  Link as LinkIcon, Database, Paperclip, MonitorOff, Volume2, VolumeX, Camera, Slash,
  Upload
} from 'lucide-react';

interface SchoolManagementProps {
  user: User;
  courses: Course[];
  activeSub: ProfessorSubView;
  selectedCourseId?: string;
}

const SchoolManagement: React.FC<SchoolManagementProps> = ({ user, courses, activeSub, selectedCourseId }) => {
  const [loading, setLoading] = useState(true);
  const [exams, setExams] = useState<Exam[]>([]);
  const [allStudents, setAllStudents] = useState<User[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([]);
  const [modules, setModules] = useState<Module[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);

  // Live States
  const [isLiveActive, setIsLiveActive] = useState(false);
  const [showLobby, setShowLobby] = useState(false);
  const [micActive, setMicActive] = useState(true);
  const [videoActive, setVideoActive] = useState(true);
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [devices, setDevices] = useState<{audio: MediaDeviceInfo[], video: MediaDeviceInfo[]}>({audio: [], video: []});
  const [selectedDevices, setSelectedDevices] = useState({audio: '', video: ''});
  const [bgEffect, setBgEffect] = useState<'none' | 'blur' | 'office' | 'custom'>('none');
  const [globalMute, setGlobalMute] = useState(false);
  const [blockCameras, setBlockCameras] = useState(false);
  const [isPresentationMode, setIsPresentationMode] = useState(false);
  const [activePanel, setActivePanel] = useState<'none' | 'chat' | 'participants' | 'settings'>('none');
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{user: string, text: string, time: string}[]>([]);
  const [selectedFileUrl, setSelectedFileUrl] = useState<string | null>(null);
  const [showPptUpload, setShowPptUpload] = useState(false);

  // Academic States
  const [selectedCourseForModules, setSelectedCourseForModules] = useState<string>(selectedCourseId || (courses[0]?.id || ''));
  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false);
  const [isLessonModalOpen, setIsLessonModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [fullScreenMode, setFullScreenMode] = useState<'none' | 'exam_editor' | 'course_preview'>('none');

  // Form States
  const [moduleTitle, setModuleTitle] = useState('');
  const [materialTitle, setMaterialTitle] = useState('');
  const [materialUrl, setMaterialUrl] = useState('');
  const [currentModuleId, setCurrentModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonForm, setLessonForm] = useState({ title: '', videoUrl: '', description: '', materialUrl: '' });
  const [examForm, setExamForm] = useState<Partial<Exam>>({ title: '', courseId: '', moduleId: '', type: 'activity', passingGrade: 70, questions: [] });
  const [questionForm, setQuestionForm] = useState<Question>({ id: '', text: '', options: ['', '', '', ''], correctOption: 0 });
  const [selectedDateForSchedule, setSelectedDateForSchedule] = useState<string>('');

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    const unsubscribes: (() => void)[] = [];
    setLoading(true);

    unsubscribes.push(onSnapshot(collection(db, 'exams'), (snap) => {
      setExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
    }));

    unsubscribes.push(onSnapshot(query(collection(db, 'scheduledClasses'), where('professorId', '==', user.uid)), (snap) => {
      setScheduledClasses(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass)));
    }));

    if (selectedCourseForModules) {
      unsubscribes.push(onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', selectedCourseForModules)), (snap) => {
        setModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0)));
      }));
    }

    unsubscribes.push(onSnapshot(collection(db, 'materials'), (snap) => {
      setMaterials(snap.docs.map(d => ({ id: d.id, ...d.data() } as Material)));
    }));

    unsubscribes.push(onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setFeedbacks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Feedback)));
    }));

    getDocs(query(collection(db, 'users'), where('role', '==', 'aluno'))).then(snap => {
      setAllStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    navigator.mediaDevices.enumerateDevices().then(d => {
      const v = d.filter(i => i.kind === 'videoinput');
      const a = d.filter(i => i.kind === 'audioinput');
      setDevices({ audio: a, video: v });
      if (v.length > 0) setSelectedDevices(prev => ({ ...prev, video: v[0].deviceId }));
      if (a.length > 0) setSelectedDevices(prev => ({ ...prev, audio: a[0].deviceId }));
    });

    return () => unsubscribes.forEach(unsub => unsub());
  }, [selectedCourseForModules, user.uid]);

  const startLiveMedia = async () => {
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    try {
      const constraints = {
        video: selectedDevices.video ? { deviceId: { exact: selectedDevices.video } } : true,
        audio: selectedDevices.audio ? { deviceId: { exact: selectedDevices.audio } } : true
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      if (lobbyVideoRef.current) lobbyVideoRef.current.srcObject = stream;
    } catch (err) { console.error("Media Error:", err); }
  };

  const handleSaveLesson = async () => {
    if (!currentModuleId || !lessonForm.title) return;
    const modRef = doc(db, 'modulos', currentModuleId);
    const modSnap = await getDoc(modRef);
    if (!modSnap.exists()) return;
    const moduleData = modSnap.data() as Module;
    let lessons = [...(moduleData.lessons || [])];
    if (editingLessonId) {
      lessons = lessons.map(l => l.id === editingLessonId ? { ...l, ...lessonForm } : l);
    } else {
      lessons.push({ id: Math.random().toString(36).substr(2, 9), ...lessonForm, order: lessons.length + 1 });
    }
    await updateDoc(modRef, { lessons });
    setIsLessonModalOpen(false);
  };

  const addQuestionToExam = () => {
    if (!questionForm.text) return;
    const newQ = { ...questionForm, id: Math.random().toString(36).substr(2, 9) };
    setExamForm(prev => ({ ...prev, questions: [...(prev.questions || []), newQ] }));
    setQuestionForm({ id: '', text: '', options: ['', '', '', ''], correctOption: 0 });
  };

  const removeQuestion = (id: string) => {
    setExamForm(prev => ({ ...prev, questions: prev.questions?.filter(q => q.id !== id) }));
  };

  const saveExam = async () => {
    if (!examForm.title) return;
    const payload = { ...examForm, authorId: user.uid, createdAt: serverTimestamp() };
    if (examForm.id) {
      await updateDoc(doc(db, 'exams', examForm.id), payload);
    } else {
      await addDoc(collection(db, 'exams'), payload);
    }
    setFullScreenMode('none');
  };

  if (fullScreenMode === 'exam_editor') {
    return (
      <div className="fixed inset-0 z-[1500] bg-[#f8fafc] flex flex-col text-slate-900 animate-in fade-in duration-300">
        <header className="bg-white border-b border-slate-200 px-8 py-5 flex items-center justify-between shadow-sm">
          <div className="flex items-center gap-4">
            <button onClick={() => setFullScreenMode('none')} className="p-2.5 bg-slate-50 rounded-full hover:bg-slate-100 transition-all"><ChevronLeft size={20}/></button>
            <div>
              <h2 className="text-sm font-black uppercase italic tracking-tighter">Editor de Exame: {examForm.title || 'Novo Exame'}</h2>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">REF: {examForm.id || 'TEMPORÁRIO'}</p>
            </div>
          </div>
          <button onClick={saveExam} className="bg-[#1e293b] text-white px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-slate-200">Finalizar Gestão</button>
        </header>

        <div className="flex-1 flex overflow-hidden p-8 gap-8">
          <aside className="w-[400px] bg-white rounded-[3rem] p-10 shadow-2xl shadow-slate-200/50 border border-slate-100 flex flex-col gap-8 overflow-y-auto">
             <div className="flex items-center gap-3">
               <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg"><Plus size={20}/></div>
               <h3 className="text-xs font-black uppercase italic tracking-widest">Novo Item Acadêmico</h3>
             </div>

             <div className="space-y-6">
                <textarea 
                  value={questionForm.text} 
                  onChange={e => setQuestionForm({...questionForm, text: e.target.value})} 
                  placeholder="Enunciado da questão..." 
                  className="w-full bg-[#f1f5f9] border-none rounded-[2rem] p-8 text-xs font-medium focus:ring-2 focus:ring-indigo-500 h-40 resize-none"
                />

                <div className="space-y-3">
                  {questionForm.options.map((opt, idx) => (
                    <div key={idx} className="flex items-center gap-4">
                      <button 
                        onClick={() => setQuestionForm({...questionForm, correctOption: idx})}
                        className={`w-10 h-10 rounded-xl flex items-center justify-center text-[10px] font-black transition-all shadow-sm
                          ${questionForm.correctOption === idx ? 'bg-emerald-500 text-white' : 'bg-white text-slate-400 border border-slate-100'}`}
                      >
                        {String.fromCharCode(65 + idx)}
                      </button>
                      <input 
                        value={opt} 
                        onChange={e => {
                          const opts = [...questionForm.options];
                          opts[idx] = e.target.value;
                          setQuestionForm({...questionForm, options: opts});
                        }}
                        placeholder={`Alternativa ${String.fromCharCode(65 + idx)}...`}
                        className="flex-1 bg-white border border-slate-100 rounded-2xl px-6 py-4 text-[10px] font-bold focus:ring-2 focus:ring-indigo-500 shadow-sm"
                      />
                    </div>
                  ))}
                </div>

                <button 
                  onClick={addQuestionToExam}
                  className="w-full bg-indigo-600 text-white py-5 rounded-[2rem] text-[10px] font-black uppercase italic tracking-[0.2em] shadow-2xl shadow-indigo-200 mt-4 active:scale-95 transition-all"
                >
                  Anexar ao Banco
                </button>
             </div>
          </aside>

          <main className="flex-1 bg-white rounded-[3rem] shadow-2xl shadow-slate-200/50 border border-slate-100 overflow-hidden flex flex-col">
            <div className="px-10 py-6 border-b border-slate-50 flex items-center justify-between bg-slate-50/30">
              <div className="flex items-center gap-3">
                <ListOrdered className="text-indigo-600" size={20}/>
                <h3 className="text-xs font-black uppercase italic tracking-widest">Banco de Questões ({examForm.questions?.length || 0})</h3>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-10 space-y-6">
              {examForm.questions?.map((q, idx) => (
                <div key={q.id} className="p-8 bg-white border border-slate-100 rounded-[2rem] hover:border-indigo-200 transition-all group relative">
                  <div className="flex items-start gap-6">
                    <div className="w-10 h-10 bg-slate-900 text-white rounded-xl flex items-center justify-center text-xs font-black">#{idx + 1}</div>
                    <div className="flex-1">
                      <p className="font-black text-sm text-slate-800 uppercase italic tracking-tight mb-6">{q.text}</p>
                      <div className="grid grid-cols-2 gap-4">
                        {q.options.map((opt, oIdx) => (
                          <div key={oIdx} className={`p-4 rounded-2xl text-[10px] font-bold border ${q.correctOption === oIdx ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-white border-slate-50 text-slate-400 opacity-60'}`}>
                            {opt}
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                  <button onClick={() => removeQuestion(q.id)} className="absolute top-8 right-8 p-3 text-rose-500 opacity-0 group-hover:opacity-100 transition-all hover:bg-rose-50 rounded-xl">
                    <Trash2 size={18}/>
                  </button>
                </div>
              ))}
              {(!examForm.questions || examForm.questions.length === 0) && (
                <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-4 py-20">
                  <ClipboardList size={60} strokeWidth={1} />
                  <p className="text-[10px] font-black uppercase italic tracking-widest">Nenhuma questão adicionada ao exame.</p>
                </div>
              )}
            </div>
          </main>
        </div>
      </div>
    );
  }

  if (isLiveActive) {
    return (
      <div className="fixed inset-0 z-[2000] bg-[#0c111d] flex flex-col text-white overflow-hidden font-sans">
        <div className="absolute top-6 left-8 right-8 z-[2100] flex items-center justify-between pointer-events-none">
          <div className="flex items-center gap-3 pointer-events-auto">
            <div className="bg-rose-600 px-6 py-2.5 rounded-2xl flex items-center gap-3 shadow-2xl border border-rose-500/20">
              <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>
              <span className="text-[9px] font-black uppercase italic tracking-widest text-white">AO VIVO</span>
            </div>
            <div className="bg-[#1e293b]/80 backdrop-blur-2xl px-6 py-2.5 rounded-2xl border border-white/10 flex items-center gap-3 text-[9px] font-black uppercase tracking-widest shadow-xl">
              <Users size={16} className="text-indigo-400"/> 0 ALUNOS ONLINE
            </div>
          </div>

          <div className="bg-indigo-600 px-6 py-2.5 rounded-2xl text-[9px] font-black uppercase tracking-widest flex items-center gap-3 shadow-2xl pointer-events-auto border border-white/10">
            <ShieldCheck size={18}/> {user.displayName}
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <main className="flex-1 relative flex items-center justify-center p-12 lg:p-20">
            <div className="w-full h-full max-w-[1400px] aspect-video bg-black rounded-[4rem] overflow-hidden border border-white/5 relative shadow-[0_0_100px_rgba(0,0,0,0.5)] group">
               {isPresentationMode && selectedFileUrl ? (
                 <div className="w-full h-full bg-white flex flex-col items-center justify-center p-20 animate-in zoom-in duration-500">
                    <div className="bg-indigo-50 px-6 py-2 rounded-xl text-[8px] font-black text-indigo-600 uppercase mb-4">Academic Asset Active</div>
                    <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter mb-12">{selectedFileUrl.split('/').pop()}</h2>
                    <div className="w-full max-w-4xl aspect-[4/3] bg-slate-50 border-4 border-slate-100 rounded-[3rem] flex items-center justify-center relative">
                       <Presentation size={100} className="text-slate-200" />
                       <p className="absolute bottom-12 text-[10px] font-black text-slate-400 uppercase tracking-widest">Interação Pedagógica em Tempo Real</p>
                       <button className="absolute left-8 top-1/2 -translate-y-1/2 p-6 bg-white rounded-full shadow-2xl hover:scale-110 transition-all"><ChevronLeft size={30} className="text-slate-400"/></button>
                       <button className="absolute right-8 top-1/2 -translate-y-1/2 p-6 bg-white rounded-full shadow-2xl hover:scale-110 transition-all"><ChevronRight size={30} className="text-slate-400"/></button>
                    </div>
                 </div>
               ) : (
                 <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-1000 ${videoActive ? 'opacity-100' : 'opacity-0'}`} />
               )}

               {!videoActive && !isPresentationMode && (
                 <div className="absolute inset-0 bg-[#0f172a] flex flex-col items-center justify-center">
                    <div className="w-32 h-32 bg-indigo-600 rounded-full flex items-center justify-center text-5xl font-black shadow-2xl shadow-indigo-900/50 mb-6 border-4 border-white/10">{(user.displayName||'U').charAt(0)}</div>
                    <p className="text-[10px] font-black uppercase italic tracking-[0.3em] text-slate-500">Câmera em Pausa</p>
                 </div>
               )}

               <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-[#1e293b]/90 backdrop-blur-3xl px-12 py-6 rounded-[3rem] border border-white/10 shadow-[0_30px_60px_-15px_rgba(0,0,0,0.5)] z-[2200]">
                  <div className="flex items-center gap-4 pr-6 border-r border-white/10">
                    <button onClick={() => { const t = streamRef.current?.getAudioTracks()[0]; if(t){t.enabled=!t.enabled; setMicActive(t.enabled);} }} className={`p-4 rounded-2xl transition-all ${micActive ? 'bg-white/5 text-white hover:bg-white/10' : 'bg-rose-600 text-white shadow-lg shadow-rose-900/40'}`}>
                      {micActive ? <Mic size={22}/> : <MicOff size={22}/>}
                    </button>
                    <button onClick={() => { const t = streamRef.current?.getVideoTracks()[0]; if(t){t.enabled=!t.enabled; setVideoActive(t.enabled);} }} className={`p-4 rounded-2xl transition-all ${videoActive ? 'bg-white/5 text-white hover:bg-white/10' : 'bg-rose-600 text-white shadow-lg shadow-rose-900/40'}`}>
                      {videoActive ? <Video size={22}/> : <VideoOff size={22}/>}
                    </button>
                    <button className="p-4 bg-white/5 rounded-2xl hover:bg-white/10"><Monitor size={22}/></button>
                    <button onClick={() => setShowPptUpload(true)} className={`p-4 rounded-2xl transition-all ${isPresentationMode ? 'bg-indigo-600 shadow-lg shadow-indigo-900/40' : 'bg-white/5 hover:bg-white/10'}`}>
                      <Presentation size={22}/>
                    </button>
                  </div>

                  <div className="flex items-center gap-4 px-6 border-r border-white/10">
                    {['👏', '❤️', '🔥', '🙌'].map(e => <button key={e} className="text-2xl hover:scale-125 transition-transform active:scale-95">{e}</button>)}
                  </div>

                  <button onClick={() => setIsLiveActive(false)} className="bg-rose-600 text-white px-10 py-4 rounded-[1.5rem] text-[9px] font-black uppercase italic tracking-widest flex items-center gap-3 shadow-2xl shadow-rose-900/40 hover:bg-rose-500 transition-all active:scale-95">
                    <PhoneOff size={20}/> Encerrar Aula
                  </button>
               </div>
            </div>
          </main>

          <aside className="w-[450px] bg-[#0c111d] border-l border-white/5 flex flex-col p-10 gap-10">
             <div className="flex items-center justify-between">
               <h3 className="text-[11px] font-black uppercase italic tracking-[0.2em] text-indigo-400">Setup Studio</h3>
               <button onClick={() => setIsLiveActive(false)} className="p-3 bg-white/5 rounded-xl hover:bg-white/10"><X size={20}/></button>
             </div>

             <div className="space-y-10">
                <div className="space-y-4">
                  <h4 className="text-[9px] font-black uppercase text-slate-500 tracking-widest italic">Mídia Master</h4>
                  <div className="space-y-3">
                    <div className="bg-white/5 border border-white/10 rounded-2xl p-5 flex items-center gap-4">
                       <Camera className="text-indigo-400" size={18}/>
                       <span className="text-[10px] font-black uppercase flex-1 truncate">{devices.video.find(d => d.deviceId === selectedDevices.video)?.label || 'Webcam'}</span>
                    </div>
                    <div className="bg-white/5 border border-white/10 rounded-2xl p-5 flex items-center gap-4">
                       <Mic className="text-indigo-400" size={18}/>
                       <span className="text-[10px] font-black uppercase flex-1 truncate">{devices.audio.find(d => d.deviceId === selectedDevices.audio)?.label || 'Microfone'}</span>
                    </div>
                  </div>
                </div>

                <div className="space-y-4">
                  <h4 className="text-[9px] font-black uppercase text-slate-500 tracking-widest italic">Efeitos Visuais</h4>
                  <div className="grid grid-cols-2 gap-3">
                    {[
                      {id:'none', icon: <Video/>, label: 'None'},
                      {id:'blur', icon: <Sparkles/>, label: 'Blur'},
                      {id:'office', icon: <ImageIcon/>, label: 'Office'},
                      {id:'custom', icon: <Upload/>, label: 'Custom'}
                    ].map(fx => (
                      <button 
                        key={fx.id} 
                        onClick={() => setBgEffect(fx.id as any)}
                        className={`p-6 rounded-3xl border transition-all flex flex-col items-center gap-3 group
                          ${bgEffect === fx.id ? 'bg-indigo-600 border-indigo-500 shadow-xl' : 'bg-white/5 border-white/5 hover:border-white/10'}`}
                      >
                        <span className={bgEffect === fx.id ? 'text-white' : 'text-slate-500 group-hover:text-indigo-400'}>{fx.icon}</span>
                        <span className="text-[8px] font-black uppercase">{fx.label}</span>
                      </button>
                    ))}
                  </div>
                </div>
             </div>

             <div className="mt-auto space-y-4">
                <button onClick={() => setActivePanel('chat')} className="w-full flex items-center justify-between p-5 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5">
                   <div className="flex items-center gap-3"><MessageSquare size={18} className="text-indigo-400"/> <span className="text-[10px] font-black uppercase tracking-widest">Abrir Chat</span></div>
                   <div className="bg-rose-600 text-white text-[8px] font-black w-5 h-5 rounded-full flex items-center justify-center">3</div>
                </button>
             </div>
          </aside>
        </div>

        {showPptUpload && (
          <div className="fixed inset-0 z-[3000] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-8">
            <div className="bg-white w-full max-w-2xl rounded-[4rem] p-16 shadow-2xl text-slate-900 text-center animate-in zoom-in-95 duration-300">
               <div className="w-24 h-24 bg-indigo-50 text-indigo-600 rounded-[2rem] flex items-center justify-center mx-auto mb-10"><Presentation size={48}/></div>
               <h3 className="text-4xl font-black uppercase italic tracking-tighter mb-4">Exposição de Slides</h3>
               <p className="text-slate-400 text-xs font-medium uppercase tracking-[0.2em] mb-12">Escolha o documento pedagógico master para exibir agora</p>

               <div className="grid grid-cols-1 gap-4 max-h-[300px] overflow-y-auto mb-12 p-2">
                 {materials.filter(m => m.type === 'pdf').map(m => (
                   <button 
                    key={m.id} 
                    onClick={() => { setSelectedFileUrl(m.url); setIsPresentationMode(true); setShowPptUpload(false); }}
                    className="p-8 rounded-[2rem] border-2 border-slate-50 hover:border-indigo-600 text-left flex items-center justify-between group transition-all"
                   >
                     <div className="flex items-center gap-6">
                        <FileText className="text-indigo-600" size={30}/>
                        <span className="font-black text-sm uppercase italic tracking-tight">{m.title}</span>
                     </div>
                     <ChevronRight className="opacity-0 group-hover:opacity-100 transition-opacity" />
                   </button>
                 ))}
               </div>

               <div className="flex gap-4">
                  <button onClick={() => setShowPptUpload(false)} className="flex-1 py-6 bg-slate-100 rounded-3xl text-[10px] font-black uppercase italic hover:bg-slate-200 transition-all">Voltar</button>
