                          <div className="p-4 bg-white rounded-2xl shadow-sm text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white transition-all"><CalendarIcon size={20}/></div>
                          <div className="flex flex-col">
                            <span className="font-black uppercase italic text-slate-800 text-sm tracking-tight">{s.title}</span>
                            <span className="text-[9px] font-black uppercase text-slate-400 tracking-widest">{s.date}</span>
                          </div>
                       </div>
                       <button className="p-3 text-slate-300 hover:text-indigo-600"><MoreVertical size={20}/></button>
                    </div>
                  ))}
                  {scheduledClasses.length === 0 && (
                    <div className="py-12 text-center text-slate-300 uppercase italic font-black text-[10px] tracking-widest border-2 border-dashed border-slate-100 rounded-[3rem]">Nenhum evento agendado.</div>
                  )}
                </div>
              </div>
              <button onClick={() => setIsScheduleModalOpen(true)} className="w-full py-6 bg-slate-50 text-slate-600 rounded-[2rem] text-[9px] font-black uppercase italic tracking-widest hover:bg-indigo-50 hover:text-indigo-600 transition-all mt-8">Agendar Novo Encontro</button>
           </div>
        </div>
      )}

      {isScheduleModalOpen && (
        <div className="fixed inset-0 z-[2000] flex items-center justify-center p-8 bg-slate-950/90 backdrop-blur-2xl">
          <div className="bg-white w-full max-w-xl rounded-[4rem] p-16 text-slate-900 shadow-2xl animate-in zoom-in-95">
            <h3 className="text-4xl font-black uppercase italic tracking-tighter text-center mb-12">Programar Aula</h3>
            <div className="space-y-6">
              <input id="sched-title" placeholder="Tema do Encontro..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-3xl font-black text-xs shadow-sm" />
              <input id="sched-date" type="datetime-local" className="w-full px-10 py-6 bg-slate-50 border-none rounded-3xl font-black text-xs shadow-sm uppercase" />
            </div>
            <div className="flex gap-4 mt-12">
              <button onClick={() => setIsScheduleModalOpen(false)} className="flex-1 py-7 bg-slate-100 rounded-[2rem] text-[10px] font-black uppercase italic tracking-widest hover:bg-slate-200 transition-all">Cancelar</button>
              <button onClick={async () => {
                const title = (document.getElementById('sched-title') as HTMLInputElement).value;
                const date = (document.getElementById('sched-date') as HTMLInputElement).value;
                if (title && date) {
                  await addDoc(collection(db, 'scheduledClasses'), { professorId: user.uid, courseId: selectedCourseForModules, title, date, status: 'scheduled', createdAt: serverTimestamp() });
                  setIsScheduleModalOpen(false);
                }
              }} className="flex-1 py-7 bg-indigo-600 text-white rounded-[2rem] text-[10px] font-black uppercase italic tracking-widest shadow-2xl shadow-indigo-100 hover:bg-indigo-700 transition-all">Confirmar Data</button>
            </div>
          </div>
        </div>
      )}

      {isModuleModalOpen && (
        <div className="fixed inset-0 z-[2000] flex items-center justify-center p-8 bg-slate-950/90 backdrop-blur-2xl">
          <div className="bg-white w-full max-w-lg rounded-[4rem] p-16 text-center text-slate-900 shadow-2xl animate-in zoom-in-95">
            <h3 className="text-4xl font-black uppercase italic tracking-tighter mb-12">{currentModuleId ? 'Editar Módulo' : 'Novo Módulo Master'}</h3>
            <input value={moduleTitle} onChange={e => setModuleTitle(e.target.value)} placeholder="Título do Módulo..." className="w-full px-10 py-6 bg-slate-50 border-none rounded-3xl font-black text-xs mb-12 shadow-sm text-center" />
            <div className="flex gap-4">
              <button onClick={() => setIsModuleModalOpen(false)} className="flex-1 py-7 bg-slate-100 rounded-[2rem] text-[10px] font-black uppercase italic tracking-widest">Sair</button>
              <button onClick={async () => {
                if(!moduleTitle) return;
                if(currentModuleId) await updateDoc(doc(db, 'modulos', currentModuleId), { title: moduleTitle });
                else await addDoc(collection(db, 'modulos'), { courseId: selectedCourseForModules, title: moduleTitle, order: modules.length+1, lessons: [], createdAt: serverTimestamp() });
                setIsModuleModalOpen(false);
              }} className="flex-1 py-7 bg-indigo-600 text-white rounded-[2rem] text-[10px] font-black uppercase italic shadow-2xl shadow-indigo-100">Gravar Módulo</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SchoolManagement;
